import{_ as t,o as a,c as r,a0 as o}from"./chunks/framework.ZNXClGez.js";const p=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/architecture.md","filePath":"getting-started/architecture.md"}'),s={name:"getting-started/architecture.md"};function n(c,e,i,h,d,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><h2 id="server-api" tabindex="-1">Server API <a class="header-anchor" href="#server-api" aria-label="Permalink to &quot;Server API&quot;">​</a></h2><p>The server component is the heart 🧡 of the authup ecosystem and can be used without any other component. It provides an HTTP-API interface to interact with various resources.</p><p>These endpoints can be inspected after starting the application under the <code>/docs</code> endpoint. Also, client libraries for <a href="./../sdks/javascript/access/">JavaScript</a> and <a href="./../sdks/python/index.html">Python</a> provide a way to interact with the architecture in a more secure way.</p><h2 id="consoles" tabindex="-1">Consoles <a class="header-anchor" href="#consoles" aria-label="Permalink to &quot;Consoles&quot;">​</a></h2><p>The server serves three web surfaces on its own origin: the hosted auth pages (login, consent, registration, password recovery), the account console at <code>/console/account</code> (end-user self-service) and the admin console at <code>/console/admin</code> (management of realms, users, clients, roles and everything else the API holds). All three are Vue 3 applications built on the frontend components of the client package, which can also be used in a custom user interface. Read more <a href="./../sdks/javascript/client-web-kit/">here</a>.</p>',6)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
